require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';require_once __DIR__ . '/../includes/student_records.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}$preview=$_SESSION['student_import_preview']??null;$token=$_POST['preview_token']??'';if(!is_array($preview)||!is_string($token)||!isset($preview['token'])||!hash_equals((string)$preview['token'],$token)||(int)($preview['created_at']??0)<time()-1200||!empty($preview['errors'])||empty($preview['rows'])||count($preview['rows'])>2000){unset($_SESSION['student_import_preview']);$_SESSION['error']='The learner import preview is invalid or expired. Upload the CSV again.';header('Location: ../?page=students');exit;}
$pdo=db();try{$pdo->beginTransaction();$term=current_school_term($pdo);$classCheck=$pdo->prepare('SELECT id FROM class_groups WHERE academic_year=:year AND form_level=:form AND stream=:stream FOR UPDATE');$checkedClasses=[];foreach($preview['rows'] as $classRow){$classKey=hash('sha256',json_encode([(int)$classRow['form_level'],(string)($classRow['stream']??'')]));if(isset($checkedClasses[$classKey]))continue;$classCheck->execute(['year'=>$term['year'],'form'=>$classRow['form_level'],'stream'=>$classRow['stream']?:'']);if(!$classCheck->fetchColumn())throw new DomainException('Create a class group for every form and stream in this CSV before confirming the learner import.');$checkedClasses[$classKey]=true;}$studentInsert=$pdo->prepare('INSERT INTO students(admission_no,first_name,last_name,national_id,sex,date_of_birth,form_level,stream,guardian_name,guardian_phone,guardian_email,address) VALUES(:admission,:first,:last,:national,:sex,:dob,:form,:stream,:guardian,:phone,:email,:address)');$guardianInsert=$pdo->prepare("INSERT INTO student_guardians(student_id,full_name,relationship,phone,email,is_primary,consent_status,consent_method,consent_recorded_at,consent_reference,recorded_by) VALUES(:student,:name,:relationship,:phone,:email,1,'Pending',NULL,NULL,NULL,:user)");$enrolmentInsert=$pdo->prepare("INSERT INTO student_enrolments(student_id,academic_year,term_number,form_level,stream,start_date,status,recorded_by) VALUES(:student,:year,:term,:form,:stream,CURDATE(),'Enrolled',:user)");$formCounts=[];foreach($preview['rows'] as $data){$studentInsert->execute(['admission'=>$data['admission_no'],'first'=>$data['first_name'],'last'=>$data['last_name'],'national'=>$data['national_id']?:null,'sex'=>$data['sex'],'dob'=>$data['date_of_birth']?:null,'form'=>$data['form_level'],'stream'=>$data['stream']?:null,'guardian'=>$data['guardian_name']?:null,'phone'=>$data['guardian_phone']?:null,'email'=>$data['guardian_email']?:null,'address'=>$data['address']?:null]);$studentId=(int)$pdo->lastInsertId();if($data['guardian_name']!=='')$guardianInsert->execute(['student'=>$studentId,'name'=>$data['guardian_name'],'relationship'=>$data['guardian_relationship'],'phone'=>$data['guardian_phone'],'email'=>$data['guardian_email']?:null,'user'=>$user['id']]);$enrolmentInsert->execute(['student'=>$studentId,'year'=>$term['year'],'term'=>$term['term'],'form'=>$data['form_level'],'stream'=>$data['stream']?:null,'user'=>$user['id']]);$formCounts[$data['form_level']]=($formCounts[$data['form_level']]??0)+1;}$count=count($preview['rows']);audit_log('student.bulk_imported','students',null,['count'=>$count,'academic_year'=>$term['year'],'form_counts'=>$formCounts,'source_file'=>$preview['file_name']??'CSV']);$pdo->commit();unset($_SESSION['student_import_preview']);$_SESSION['notice']=$count.' learners imported. Guardian contacts were saved with consent pending; review them before creating guardian logins.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Learner CSV import failed: '.$e->getMessage());$_SESSION['error']=$e instanceof DomainException?$e->getMessage():($e instanceof PDOException&&$e->getCode()==='23000'?'Import stopped because an admission number is already in use. No learner rows were added; preview the CSV again.':'Import failed. The transaction was rolled back and no learner rows were added.');}header('Location: ../?page=students');exit;
